import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

import { parseCanonicalJsonBytes } from "@hadith-archive/canonical-json";
import { RECORD_SCHEMA_CATALOG } from "../src/catalog.ts";

const BANNER = `/**
 * Generated from the authoritative JSON Schemas.
 * Do not edit this file by hand; run \`bun run generate:types\`.
 */
`;

export const GENERATED_RECORD_TYPES_PATH =
  "packages/core-loader/src/generated/records.ts";

async function compileSchema(
  schemaPath: string,
  schema: object,
): Promise<string> {
  const executable = resolve(
    import.meta.dir,
    "../node_modules/.bin/json2ts",
  );
  const process = Bun.spawn(
    [
      executable,
      `--cwd=${dirname(schemaPath)}`,
      "--no-additionalProperties",
      "--declareExternallyReferenced",
      "--no-enableConstEnums",
      "--unknownAny",
    ],
    {
      stderr: "pipe",
      stdin: new Blob([JSON.stringify(schema)]),
      stdout: "pipe",
    },
  );
  const [exitCode, output, diagnostic] = await Promise.all([
    process.exited,
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
  ]);

  if (exitCode !== 0) {
    throw new Error(`json2ts failed for ${schemaPath}: ${diagnostic.trim()}`);
  }

  return output
    .replace(/^\/\*[\s\S]*?\*\/\s*/, "")
    .replace(
      /^\/\*\*\n \* This file was automatically generated by json-schema-to-typescript\.[\s\S]*?\*\/\s*/,
      "",
    )
    .trim();
}

export async function generateRecordTypes(
  repositoryRoot: string,
): Promise<string> {
  const declarations: string[] = [];

  for (const entry of RECORD_SCHEMA_CATALOG) {
    const schemaPath = resolve(repositoryRoot, "schemas", entry.relativePath);
    const schema = parseCanonicalJsonBytes(await readFile(schemaPath));
    Reflect.deleteProperty(schema, "$id");
    schema["title"] = entry.typeName;
    declarations.push(await compileSchema(schemaPath, schema));
  }

  const union = RECORD_SCHEMA_CATALOG.map((entry) => entry.typeName).join(
    "\n  | ",
  );

  return `${BANNER}\n${declarations.join("\n\n")}\n\nexport type HadithArchiveRecord =\n  | ${union};\n`;
}
